edits.before:
display: flex;
align-items: center;
justify-content: space-between;
margin-bottom: 8px;

display: inline-block;
margin-left: 6px;
padding: 1px 6px;
font-size: 10px;
font-weight: 500;
color: var(--text-muted);
background: var(--bg-tertiary, rgba(128,128,128,0.08));
border-radius: 8px;

edits.after:
display: inline-block; margin-left: 6px; padding: 1px 6px;
font-size: 10px; font-weight: 500; color: var(--text-muted);
background: var(--bg-tertiary, rgba(128,128,128,0.08)); border-radius: 8px;

edits.before:
padding: 4px 10px;
font-size: 11px;
font-weight: 600;
background: transparent;
color: var(--accent);
border: 1px solid var(--accent);
border-radius: 6px;
cursor: pointer;

edits.after:
padding: 4px 10px; font-size: 11px; font-weight: 600;
background: transparent; color: var(--accent);
border: 1px solid var(--accent); border-radius: 6px;
cursor: pointer;

edits.before:
list-style: none;
padding: 0;
margin: 0;
max-height: 240px;
overflow-y: auto;
border: 1px solid var(--border);
border-radius: 6px;

edits.after:
list-style: none; padding: 0; margin: 0;
max-height: 240px; overflow-y: auto;
border: 1px solid var(--border); border-radius: 6px;

edits.before:
display: flex;
align-items: center;
gap: 10px;
padding: 6px 10px;
font-size: 12px;
border-bottom: 1px solid var(--border);

edits.after:
display: flex; align-items: center; gap: 10px;
padding: 6px 10px; font-size: 12px;
border-bottom: 1px solid var(--border);

edits.before:
font-size: 9px;
padding: 1px 5px;
border-radius: 8px;
background: var(--bg-tertiary, rgba(128,128,128,0.08));
color: var(--text-muted);
text-transform: lowercase;

edits.after:
font-size: 9px; padding: 1px 5px; border-radius: 8px;
background: var(--bg-tertiary, rgba(128,128,128,0.08));
color: var(--text-muted); text-transform: lowercase;

edits.before:
margin-left: auto;
padding: 2px 7px;
font-size: 13px;
line-height: 1;
background: transparent;
border: 0;
color: var(--text-muted);
cursor: pointer;
border-radius: 4px;

edits.after:
margin-left: auto; padding: 2px 7px; font-size: 13px; line-height: 1;
background: transparent; border: 0; color: var(--text-muted);
cursor: pointer; border-radius: 4px;

edits.before:
flex-basis: 100%;
font-size: 11px;
color: var(--text-secondary);
font-style: italic;
margin-top: 2px;
padding-left: 0;
line-height: 1.35;
word-break: break-word;

edits.after:
flex-basis: 100%; font-size: 11px; color: var(--text-secondary);
font-style: italic; margin-top: 2px; padding-left: 0; line-height: 1.35;
word-break: break-word;

edits.before:
display: grid;
grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
gap: 10px;
margin-top: 16px;

edits.after:
display: grid;
grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
gap: 10px;
margin-top: 16px;

edits.before:
background: var(--bg-primary);
border: 1px solid var(--border);
border-radius: 8px;
padding: 10px 12px;
display: flex;
flex-direction: column;
gap: 2px;

edits.after:
background: var(--bg-primary);
border: 1px solid var(--border);
border-radius: 8px;
padding: 10px 12px;
display: flex; flex-direction: column; gap: 2px;

edits.before:
font-size: 11px;
text-transform: uppercase;
letter-spacing: 0.04em;
color: var(--text-secondary);
font-weight: 600;

edits.after:
font-size: 11px;
text-transform: uppercase;
letter-spacing: 0.04em;
color: var(--text-secondary);
font-weight: 600;

edits.before:
margin-top: 14px;
padding: 12px 14px;
background: var(--bg-primary);
border: 1px dashed var(--border);
border-radius: 8px;
font-size: 12px;
color: var(--text-secondary);
line-height: 1.5;

edits.after:
margin-top: 14px;
padding: 12px 14px;
background: var(--bg-primary);
border: 1px dashed var(--border);
border-radius: 8px;
font-size: 12px;
color: var(--text-secondary);
line-height: 1.5;

edits.before:
font-size: 12px;
color: var(--text-secondary);
margin-top: 14px;
padding: 8px 10px;
background: rgba(99, 102, 241, 0.05);
border-left: 3px solid var(--accent);
border-radius: 0 var(--radius) var(--radius) 0;
line-height: 1.5;

min-width: 44px;
min-height: 44px;
display: inline-flex;
align-items: center;
justify-content: center;
